def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out"""
    # Simple approach: find first difference and what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    pos = 0
    while pos < min_len and s_in[pos] == s_out[pos]:
        pos += 1

    # If we reached the end of one string, it's an insertion/deletion
    if pos >= len(s_in) or pos >= len(s_out):
        # Handle length differences
        if len(s_in) < len(s_out):
            # Insertion case
            return (s_in[pos:], s_out[pos:], pos)
        else:
            # Deletion case  
            return (s_in[pos:], s_out[pos:], pos)

    # Find what to replace
    old_sub = ""
    new_sub = ""

    # Look for substring matches
    for i in range(pos, len(s_in)):
        for j in range(pos, len(s_out) + 1):
            if s_in[pos:i+1] == s_out[pos:j]:
                old_sub = s_in[pos:i+1]
                new_sub = s_out[pos:j]
                break
        if old_sub:
            break

    if not old_sub:
        # Fallback: simple character-by-character comparison
        old_sub = s_in[pos:pos+1] if pos < len(s_in) else ""
        new_sub = s_out[pos:pos+1] if pos < len(s_out) else ""

    return (old_sub, new_sub, pos)

